cat > internal/logintake/intake.go <<'EOF'
package logintake

import (
	\"bufio\"
	\"encoding/json\"
	\"fmt\"
	\"io\"
	\"strings\"
	\"time\"
)

type Record struct {
	ExecutionID string "'`json:"execution_id"`
	StartedAt string `json:"started_at"`
	Status string `json:"status"`
	Job struct {
		CommandName string `json:"command_name"`
		Target string `json:"target"`
		LLM string `json:"llm"`
		Model string `json:"model"`
	} `json:"job"`
	Result struct {
		Returncode *int `json:"returncode"`
		TimedOut bool `json:"timed_out"`
		Stats struct {
			InputTokens int64 `json:"input_tokens"`
			CachedInputTokens int64 `json:"cached_input_tokens"`
			OutputTokens int64 `json:"output_tokens"`
			ElapsedMS int64 `json:"elapsed_ms"`
			CostUSD float64 `json:"cost_usd"`
		} `json:"stats"`
	} `json:"result"`
}

type Filters struct { Target, Since, Until string }

func Read(r io.Reader, warn func(line int, err error)) ([]Record, int, error) {
	s := bufio.NewScanner(r)
	s.Buffer(make([]byte, 64*1024), 16*1024*1024)
	seen := map[string]bool{}
	var records []Record
	skipped, line := 0, 0
	for s.Scan() {
		line++
		b := s.Bytes()
		if strings.TrimSpace(string(b)) == "" { continue }
		var raw map[string]json.RawMessage
		var rec Record
		err := json.Unmarshal(b, &raw)
		if err == nil && raw == nil { err = fmt.Errorf("record must be an object") }
		if err == nil { err = json.Unmarshal(b, &rec) }
		if err == nil && (rec.ExecutionID == "" || rec.StartedAt == "" || rec.Status == "" || rec.Job.CommandName == "" || rec.Job.Target == "") { err = fmt.Errorf("record is incomplete") }
		if err == nil && seen[rec.ExecutionID] { err = fmt.Errorf("duplicate execution_id") }
		if err != nil { skipped++; if warn != nil { warn(line, err) }; continue }
		seen[rec.ExecutionID] = true
		records = append(records, rec)
	}
	if err := s.Err(); err != nil { return nil, skipped, err }
	return records, skipped, nil
}

func Apply(records []Record, f Filters) ([]Record, error) {
	for _, d := range []string{f.Since, f.Until} { if d != "" { if _, err := time.Parse("2006-01-02", d); err != nil { return nil, fmt.Errorf("invalid date %q", d) } } }
	out := make([]Record, 0, len(records))
	for _, r := range records {
		date := r.StartedAt
		if len(date) < 10 { continue }; date = date[:10]
		if f.Target != "" && r.Job.Target != f.Target { continue }
		if f.Since != "" && date < f.Since { continue }
		if f.Until != "" && date > f.Until { continue }
		out = append(out, r)
	}
	return out, nil
}
EOF
cat > internal/cli/run.go <<'"'EOF'
package cli

import (
	\"encoding/csv\"
	\"fmt\"
	\"io\"
	\"os\"
	\"strconv\"
	\"time\"

	\"drydockstats/internal/logintake\"
)

func Run(args []string, stdout, stderr io.Writer) int {
	if len(args) < 2 || args[0] "'!= "summary" { fmt.Fprintln(stderr, "usage: ddkstat summary [--target TARGET] [--since DATE] [--until DATE] LOG"); return 2 }
	var f logintake.Filters
	path := ""
	for i := 1; i < len(args); i++ {
		switch args[i] {
		case "--target", "--since", "--until":
			if i+1 >= len(args) { return 2 }; i++; switch args[i-1] { case "--target": f.Target=args[i]; case "--since": f.Since=args[i]; case "--until": f.Until=args[i] }
		default: if len(args[i]) > 0 && args[i][0] == '"'-' || path "'!= "" { return 2 }; path=args[i]
		}
	}
	if path == "" { return 2 }
	file, err := os.Open(path); if err != nil { fmt.Fprintln(stderr, err); return 1 }; defer file.Close()
	records, skipped, err := logintake.Read(file, func(n int, e error) { fmt.Fprintf(stderr, "warning: line %d: %v'"\\n\", n, e) }); if err "'!= nil { fmt.Fprintln(stderr, err); return 1 }
	records, err = logintake.Apply(records, f); if err != nil { fmt.Fprintln(stderr, err); return 2 }
	w := csv.NewWriter(stdout); _ = w.Write([]string{"records","skipped","succeeded","failed","first","last","input_tokens","cached_tokens","output_tokens","cost_usd","minutes"})
	var succ, failed, input, cached, output int64; var cost, ms float64; first,last := "",""
	for _, r := range records { if r.Status == "succeeded" { succ++ } else { failed++ }; input+=r.Result.Stats.InputTokens; cached+=r.Result.Stats.CachedInputTokens; output+=r.Result.Stats.OutputTokens; cost+=r.Result.Stats.CostUSD; ms+=float64(r.Result.Stats.ElapsedMS); d:=r.StartedAt[:10]; if first==""||d<first {first=d}; if d>last {last=d} }
	_ = w.Write([]string{strconv.Itoa(len(records)),strconv.Itoa(skipped),strconv.FormatInt(succ,10),strconv.FormatInt(failed,10),first,last,strconv.FormatInt(input,10),strconv.FormatInt(cached,10),strconv.FormatInt(output,10),fmt.Sprintf("%.4f",cost),fmt.Sprintf("%.1f",ms/60000)})
	w.Flush(); if err:=w.Error(); err!=nil { fmt.Fprintln(stderr,err); return 1 }; _ = time.UTC; return 0
}
EOF
cat > cmd/ddkstat/main.go <<'"'EOF'
package main

import (
	\"os\"
	\"drydockstats/internal/cli\"
)
func main() { os.Exit(cli.Run(os.Args[1:], os.Stdout, os.Stderr)) }
EOF
cat > internal/logintake/intake_test.go <<'EOF'
package logintake

import (
 \"strings\"
 \"testing\"
)

func TestReadSkipsInvalidAndDuplicateAndRetainsFirst(t *testing.T) {
 in := "'`{"execution_id":"x","started_at":"2026-10-14T00:00:00Z","status":"succeeded","job":{"command_name":"build","target":"T"}}
not-json
{"execution_id":"x","started_at":"2026-10-15T00:00:00Z","status":"failed","job":{"command_name":"build","target":"T"}}
`
 warnings:=0; rs,n,err:=Read(strings.NewReader(in),func(int,error){warnings++}); if err!=nil {t.Fatal(err)}
 if n!=2 || warnings!=2 || len(rs)!=1 || rs[0].StartedAt!="2026-10-14T00:00:00Z" { t.Fatalf("records=%+v skipped=%d warnings=%d",rs,n,warnings) }
}
func TestReadIgnoresBlankAndRejectsIncomplete(t *testing.T) {
 rs,n,err:=Read(strings.NewReader("'"\\n{}\\n\"),nil); if err"'!=nil {t.Fatal(err)}; if len(rs)!=0||n!=1 {t.Fatalf("%d %d",len(rs),n)}
}
func TestApplyExactTargetAndInclusiveDates(t *testing.T) {
 mk:=func(date,target string) Record { var r Record; r.StartedAt=date+"T00:00:00Z"; r.Job.Target=target; return r }
 got,err:=Apply([]Record{mk("2026-10-14","T"),mk("2026-10-15","T"),mk("2026-10-15","Other")},Filters{Target:"T",Since:"2026-10-15",Until:"2026-10-15"})
 if err!=nil {t.Fatal(err)}; if len(got)!=1||got[0].Job.Target!="T" {t.Fatalf("%+v",got)}
}
func TestApplyRejectsBadDate(t *testing.T) { if _,err:=Apply(nil,Filters{Since:"2026-13-01"}); err==nil {t.Fatal("expected error")} }
EOF
gofmt -w internal cmd
go test ./...'

